#[ignore]
fn changes_east_to_south() {
    let robot_start = RobotTrait::new(0, 0, Direction::East);
    let robot_end = robot_start.turn_right();
    assert_eq!(robot_end.position(), (0, 0));
    assert_eq!(robot_end.direction(), @Direction::South);
}

